import os
import re

path = os.path.expanduser('~/.config/google-chrome/Default')
for root, dirs, files in os.walk(path):
    for f in files:
        if f.endswith('.ldb') or f.endswith('.log'):
            full = os.path.join(root, f)
            try:
                with open(full, 'rb') as fp:
                    d = fp.read()
                    if b'stsTokenManager' in d or b'apiKey' in d and b'gpt.space' in d:
                        print('Match in:', full)
                        for m in re.finditer(b'stsTokenManager', d):
                            print(repr(d[max(0, m.start()-50):min(len(d), m.start()+500)]))
            except Exception:
                pass
"

