                Plates are stamped strictly matching the official registration record.
              </p>
            </div>
          </div>
        </div>

        {errorMsg && (
          <div className="bg-red-900/40 border border-red-500 text-red-200 text-xs p-4 rounded-xl mb-6">
            {errorMsg}
          </div>
