    ["bridge_enabled", "true"],
  ]),
};

let pool: mysql.Pool | null = null;

export function getPool(): mysql.Pool | null {
  if (pool) return pool;

  const host = process.env.MYSQL_HOST;
  const user = process.env.MYSQL_USER;
  const password = process.env.MYSQL_PASSWORD;
  const database = process.env.MYSQL_DATABASE || "bnp_shop";
  const port = Number(process.env.MYSQL_PORT) || 3306;

  if (!host || !user) {
    return null;
  }

  try {
    pool = mysql.createPool({
      host,
      port,
      user,
      password,
      database,
      waitForConnections: true,
      connectionLimit: 10,
      queueLimit: 0,
      enableKeepAlive: true,
      keepAliveInitialDelay: 10000,
    });
    return pool;
  } catch (err) {
    console.warn("MySQL pool initialization failed, using memory store:", err);
    return null;
  }
}

/**
 * Executes a parameterized SQL query with graceful fallback.
 */
export async function dbQuery<T = any>(sql: string, params: any[] = []): Promise<T[]> {
  const p = getPool();
  if (p) {
    try {
      const [rows] = await p.execute(sql, params);
      return rows as T[];
    } catch (err) {
      console.error("Database query failed:", err);
      throw err;
    }
  }
  return [];
}

/**
 * Fetches dynamic store settings from the settings table.
 */
export async function getStoreSettings(): Promise<StoreSettings> {
  const p = getPool();
  const settingsMap = new Map<string, string>(memStore.settings);

  if (p) {
    try {
      const [rows] = await p.query<mysql.RowDataPacket[]>("SELECT k, v FROM settings");
      for (const row of rows) {
        settingsMap.set(row.k, row.v);
      }
    } catch (err) {
      console.warn("Could not query settings table, using defaults:", err);
    }
  }

  return {
    price_a: Number(settingsMap.get("price_a")) || 380,
    price_b: Number(settingsMap.get("price_b")) || 450,
    price_preorder_a: Number(settingsMap.get("price_preorder_a")) || 300,
    price_preorder_b: Number(settingsMap.get("price_preorder_b")) || 380,
    bracket_price: Number(settingsMap.get("bracket_price")) || 80,
    delivery_dhaka: Number(settingsMap.get("delivery_dhaka")) || 60,
    delivery_outside: Number(settingsMap.get("delivery_outside")) || 120,
    urgency_text: settingsMap.get("urgency_text") || "BRTA deadline: November 15 — order your compliant plate today",
    hotline: settingsMap.get("hotline") || "01632333221",
    whatsapp: settingsMap.get("whatsapp") || "01914-873925",
  };
}

/**
 * Updates a setting value.
 */
export async function updateStoreSetting(key: string, value: string): Promise<void> {
  memStore.settings.set(key, value);
  const p = getPool();
  if (p) {
    await p.execute(
      "INSERT INTO settings (k, v) VALUES (?, ?) ON DUPLICATE KEY UPDATE v = VALUES(v)",
      [key, value]
    );
  }
}

/**
 * Inserts a new order record into the database.
 */
export async function insertOrder(order: Omit<OrderRecord, "id" | "created_at">): Promise<OrderRecord> {
  const p = getPool();
  const now = new Date().toISOString().slice(0, 19).replace("T", " ");

  if (p) {
    const [result] = await p.execute<mysql.ResultSetHeader>(
      `INSERT INTO orders (
        order_number, name, shop_name, phone, district, address, model,
        reg_number_bangla, reg_number_english, quantity, bracket, unit_price,
        plate_total, bracket_total, delivery_charge, total, payment_status,
        payment_method, lora_session_id, lora_trx_id, trx_note, status, notes
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        order.order_number,
        order.name,
        order.shop_name,
        order.phone,
        order.district,
        order.address,
        order.model,
        order.reg_number_bangla,
        order.reg_number_english || null,
        order.quantity,
        order.bracket ? 1 : 0,
        order.unit_price,
        order.plate_total,
        order.bracket_total,
        order.delivery_charge,
        order.total,
        order.payment_status,
        order.payment_method,
        order.lora_session_id || null,
        order.lora_trx_id || null,
        order.trx_note || null,
        order.status,
        order.notes || null,
      ]
    );

    return {
      ...order,
      id: result.insertId,
      created_at: now,
    };
  }

  // Fallback memory insertion
  const id = memStore.orders.size + 1;
  const record: OrderRecord = {
    ...order,
    id,
    created_at: now,
  };
  memStore.orders.set(order.order_number, record);
  return record;
}

/**
 * Retrieves an order by order_number.
 */
export async function getOrderByNumber(orderNumber: string): Promise<OrderRecord | null> {
  const p = getPool();
  if (p) {
    const [rows] = await p.execute<mysql.RowDataPacket[]>(
      "SELECT * FROM orders WHERE order_number = ? LIMIT 1",
      [orderNumber]
    );
    if (rows.length > 0) {
      const r = rows[0];
      return {
        ...r,
        bracket: Boolean(r.bracket),
      } as OrderRecord;
    }
    return null;
  }

  return memStore.orders.get(orderNumber) || null;
}

/**
 * Updates order payment status and transaction references.
 */
export async function updateOrderPayment(
  orderNumber: string,
  paymentStatus: PaymentStatus,
  loraTrxId?: string,
  sessionStatus?: OrderStatus
): Promise<boolean> {
  const p = getPool();
  if (p) {
    const statusSql = sessionStatus ? ", status = ?" : "";
    const params: any[] = [paymentStatus];

    let updateFields = "payment_status = ?";
    if (loraTrxId) {
      updateFields += ", lora_trx_id = ?";
      params.push(loraTrxId);
    }
    if (sessionStatus) {
      updateFields += ", status = ?";
      params.push(sessionStatus);
    }
    params.push(orderNumber);

    const [res] = await p.execute<mysql.ResultSetHeader>(
      `UPDATE orders SET ${updateFields} WHERE order_number = ?`,
      params
    );
    return res.affectedRows > 0;
  }

  const existing = memStore.orders.get(orderNumber);
  if (existing) {
    existing.payment_status = paymentStatus;
    if (loraTrxId) existing.lora_trx_id = loraTrxId;
    if (sessionStatus) existing.status = sessionStatus;
    memStore.orders.set(orderNumber, existing);
    return true;
  }
  return false;
}

import crypto from "crypto";

export interface LoraBridgeSessionParams {
  reference: string;
  amount: number;
  customerName: string;
  customerPhone: string;
  customerEmail?: string;
  metadata?: Record<string, any>;
}

export interface LoraBridgeSessionResponse {
  session_id: string;
  checkout_url: string;
  reference: string;
  expires_at?: string;
}

const BRIDGE_BASE_URL = process.env.LORA_BRIDGE_URL || "https://lorahost.lorapok.tech";

/**
 * Creates a checkout session with the LoraHost Payment Bridge (PayStation relay).
 * Handles 409 duplicate-invoice retry with a fresh nonce.
 */
export async function createBridgeSession(
  params: LoraBridgeSessionParams,
  retryCount = 0
): Promise<LoraBridgeSessionResponse> {
  const token = process.env.LORA_BRIDGE_CLIENT_TOKEN;
  const siteUrl = process.env.NEXT_PUBLIC_SITE_URL || "https://bnp.shop";
  const returnUrl = `${siteUrl.replace(/\/$/, "")}/payment/return`;

  // Fallback simulation for local development without active token
  if (!token || token.includes("your_lorahost")) {
    console.warn("LORA_BRIDGE_CLIENT_TOKEN not configured. Generating simulated dev checkout session.");
    const mockSessionId = "sim_" + crypto.randomBytes(12).toString("hex");
    return {
      session_id: mockSessionId,
      checkout_url: `${returnUrl}?reference=${encodeURIComponent(params.reference)}&status=success&trx_id=SIM_TRX_${Date.now()}&amount=${params.amount}&session_id=${mockSessionId}&sig=mock_dev_signature`,
      reference: params.reference,
    };
  }

  const endpoint = `${BRIDGE_BASE_URL.replace(/\/$/, "")}/api/payment-bridge/v1/sessions`;

  const body = {
    reference: params.reference,
    amount: Math.round(params.amount),
    return_url: returnUrl,
    customer: {
      name: params.customerName,
      phone: params.customerPhone,
      email: params.customerEmail || "bikesnumberplate@gmail.com",
    },
    metadata: params.metadata || {},
  };

  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${token}`,
      "Content-Type": "application/json",
      "Accept": "application/json",
    },
    body: JSON.stringify(body),
  });

  if (response.status === 409 && retryCount < 2) {
    // 409 Duplicate PayStation invoice: create a fresh reference with a distinct nonce
    const retryRef = `${params.reference}-R${retryCount + 1}`;
    console.warn(`LoraHost returned 409 Duplicate Invoice for ${params.reference}. Retrying with fresh reference: ${retryRef}`);
    return createBridgeSession({ ...params, reference: retryRef }, retryCount + 1);
  }

  if (!response.ok) {
    const errorText = await response.text();
    let errorJson: any;
    try {
      errorJson = JSON.parse(errorText);
    } catch {
      errorJson = { message: errorText };
    }

    if (response.status === 401) {
      throw new Error("Payment bridge authentication failed (401 Unauthorized). Check LORA_BRIDGE_CLIENT_TOKEN.");
    }
    if (response.status === 403) {
      throw new Error("Payment bridge checkout token invalid or disabled (403 Forbidden).");
    }
    if (response.status === 422) {
      throw new Error(`Invalid return URL passed to payment bridge (422): ${errorJson.message || errorText}`);
    }
    if (response.status === 429) {
      throw new Error("Payment bridge rate limit exceeded (429). Please retry in a few moments.");
    }
    if (response.status === 503) {
      throw new Error("Payment bridge is currently undergoing scheduled maintenance (503). Please choose Manual bKash/Nagad.");
    }

    throw new Error(`Payment Bridge Error (${response.status}): ${errorJson.message || errorText}`);
  }

  const data = await response.json();
  return {
    session_id: data.session_id,
    checkout_url: data.checkout_url || `${BRIDGE_BASE_URL}/pay/bridge/${data.session_id}`,
    reference: data.reference || params.reference,
    expires_at: data.expires_at,
  };
}

/**
 * Verifies return URL query parameters using HMAC-SHA256.
 * Sorts query params alphabetically (excluding 'sig').
 */
export function verifyReturnSignature(params: Record<string, string | string[] | undefined>): boolean {
  const secret = process.env.LORA_RETURN_HMAC_TOKEN;
  const providedSig = params.sig;

  if (!providedSig || typeof providedSig !== "string") {
    return false;
  }

  // Allow bypass in local development if using simulated signature
  if (providedSig === "mock_dev_signature" && (!secret || secret.includes("your_lorahost"))) {
    return true;
  }

  if (!secret) {
    console.error("LORA_RETURN_HMAC_TOKEN is not configured.");
    return false;
  }

  // Construct canonical sorted query string excluding 'sig'
  const keys = Object.keys(params)
    .filter((k) => k !== "sig" && params[k] !== undefined && params[k] !== null)
    .sort();

  const canonicalString = keys
    .map((k) => `${k}=${encodeURIComponent(String(params[k]))}`)
    .join("&");

  const expectedSig = crypto
    .createHmac("sha256", secret)
    .update(canonicalString)
    .digest("hex");

  try {
    return crypto.timingSafeEqual(
      Buffer.from(providedSig, "hex"),
      Buffer.from(expectedSig, "hex")
    );
  } catch {
    return false;
  }
}

/**
 * Verifies asynchronous webhook payloads from LoraHost.
 * Verified against the RAW unparsed JSON body using LORA_WEBHOOK_HMAC_TOKEN.
 */
export function verifyWebhookSignature(rawBody: string, signatureHeader: string | null): boolean {
  if (!signatureHeader) return false;

  const secret = process.env.LORA_WEBHOOK_HMAC_TOKEN;

  // Allow bypass in local dev if using mock header
  if (signatureHeader === "mock_dev_webhook" && (!secret || secret.includes("your_lorahost"))) {
    return true;
  }

  if (!secret) {
    console.error("LORA_WEBHOOK_HMAC_TOKEN is not configured.");
    return false;
  }

  const expectedSig = crypto
    .createHmac("sha256", secret)
    .update(rawBody)
    .digest("hex");

  try {
    return crypto.timingSafeEqual(
      Buffer.from(signatureHeader, "hex"),
      Buffer.from(expectedSig, "hex")
    );
  } catch {
    return false;
  }
}

import { NextRequest, NextResponse } from "next/server";
import { insertOrder, getStoreSettings } from "@/lib/db";
import { createBridgeSession } from "@/lib/lorahost";
import { OrderInput, OrderRecord, PlateModel } from "@/lib/types";

export async function POST(req: NextRequest) {
  try {
    const body: OrderInput = await req.json();

    // 1. Validation
    const name = (body.name || "").trim();
    const phone = (body.phone || "").trim();
    const district = (body.district || "").trim();
    const address = (body.address || "").trim();
    const model = body.model as PlateModel;
    const regBangla = (body.reg_number_bangla || "").trim();
    const quantity = Math.max(1, Math.min(100, Math.floor(Number(body.quantity) || 1)));
    const bracket = Boolean(body.bracket);
    const paymentMethod = body.payment_method || "lorahost_bridge";

    if (!name || name.length < 2) {
      return NextResponse.json({ error: "Please enter your full name." }, { status: 400 });
    }

    if (!/^01[3-9]\d{8}$/.test(phone)) {
      return NextResponse.json({ error: "Please enter a valid 11-digit Bangladesh phone number." }, { status: 400 });
    }

    if (!district) {
      return NextResponse.json({ error: "Please select a delivery district." }, { status: 400 });
    }

    if (!address || address.length < 5) {
      return NextResponse.json({ error: "Please provide a complete delivery street address." }, { status: 400 });
    }

    if (model !== "A" && model !== "B") {
      return NextResponse.json({ error: "Invalid plate model selected." }, { status: 400 });
    }

    if (!regBangla) {
      return NextResponse.json({ error: "Registration plate number cannot be empty." }, { status: 400 });
    }

    // 2. Server-side Pricing Recalculation (Never trust client sent prices)
    const settings = await getStoreSettings();
    const unitPrice = model === "A" ? settings.price_a : settings.price_b;
    const plateTotal = unitPrice * quantity;
    const bracketTotal = bracket ? settings.bracket_price * quantity : 0;
    const isDhaka = district.toLowerCase() === "dhaka";
    const deliveryCharge = isDhaka ? settings.delivery_dhaka : settings.delivery_outside;
    const total = plateTotal + bracketTotal + deliveryCharge;

    // 3. Unique Reference ID
    const datePrefix = new Date().toISOString().slice(0, 10).replace(/-/g, "");
    const randomSuffix = Math.floor(1000 + Math.random() * 9000);
    const orderNumber = `BNP-${datePrefix}-${randomSuffix}`;

    // 4. Initial Database Record
    const initialPaymentStatus = paymentMethod === "lorahost_bridge" ? "pending_payment" : "verifying";
    const initialStatus = paymentMethod === "lorahost_bridge" ? "new" : "new";

    let loraSessionId: string | null = null;
    let checkoutUrl: string | null = null;

    if (paymentMethod === "lorahost_bridge") {
      const session = await createBridgeSession({
        reference: orderNumber,
        amount: total,
        customerName: name,
        customerPhone: phone,
        metadata: {
          model,
          reg_number: regBangla,
          bracket,
          quantity,
          district,
        },
      });

      loraSessionId = session.session_id;
      checkoutUrl = session.checkout_url;
    }

    await insertOrder({
      order_number: orderNumber,
      name,
      shop_name: body.shop_name ? body.shop_name.trim() : null,
      phone,
      district,
      address,
      model,
      reg_number_bangla: regBangla,
      reg_number_english: body.reg_number_english || null,
      quantity,
      bracket,
      unit_price: unitPrice,
      plate_total: plateTotal,
      bracket_total: bracketTotal,
      delivery_charge: deliveryCharge,
      total,
      payment_status: initialPaymentStatus,
      payment_method: paymentMethod,
      lora_session_id: loraSessionId,
      lora_trx_id: null,
      trx_note: body.trx_id ? body.trx_id.trim() : null,
      status: initialStatus,
      notes: null,
    });

    return NextResponse.json({
      ok: true,
      order_number: orderNumber,
      total,
      checkout_url: checkoutUrl,
    });
  } catch (err: any) {
    console.error("Order creation route error:", err);
    return NextResponse.json(
      { error: err.message || "Failed to process order." },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { verifyReturnSignature } from "@/lib/lorahost";
import { updateOrderPayment, getOrderByNumber } from "@/lib/db";

export async function GET(req: NextRequest) {
  const url = new URL(req.url);
  const searchParams = Object.fromEntries(url.searchParams.entries());

  const reference = searchParams.reference;
  const status = searchParams.status;
  const trxId = searchParams.trx_id;

  if (!reference) {
    return NextResponse.redirect(new URL("/payment/failed?reason=missing_reference", req.url));
  }

  // 1. Verify Cryptographic Return Signature
  const isValid = verifyReturnSignature(searchParams);

  if (!isValid) {
    console.error(`Invalid return HMAC signature received for order: ${reference}`);
    return NextResponse.redirect(
      new URL(`/payment/failed?order_number=${encodeURIComponent(reference)}&reason=invalid_signature`, req.url)
    );
  }

  // 2. Update Database Record
  if (status === "success") {
    await updateOrderPayment(reference, "paid", trxId, "confirmed");
    return NextResponse.redirect(
      new URL(
        `/payment/success?order_number=${encodeURIComponent(reference)}&trx_id=${encodeURIComponent(trxId || "")}&method=lorahost_bridge`,
        req.url
      )
    );
  } else {
    await updateOrderPayment(reference, "failed", trxId);
    return NextResponse.redirect(
      new URL(
        `/payment/failed?order_number=${encodeURIComponent(reference)}&reason=${encodeURIComponent(status || "payment_cancelled")}`,
        req.url
      )
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { verifyWebhookSignature } from "@/lib/lorahost";
import { updateOrderPayment, getOrderByNumber } from "@/lib/db";

export async function POST(req: NextRequest) {
  try {
    const rawBody = await req.text();
    const signature = req.headers.get("x-lorahost-signature");

    // 1. Verify Webhook Signature on Raw Body
    const isValid = verifyWebhookSignature(rawBody, signature);
    if (!isValid) {
      console.error("Webhook rejected: Invalid X-LoraHost-Signature header.");
      return NextResponse.json({ error: "Invalid webhook signature" }, { status: 401 });
    }

    const payload = JSON.parse(rawBody);
    const reference = payload.reference;
    const status = payload.status;
    const trxId = payload.trx_id;

    if (!reference) {
      return NextResponse.json({ error: "Missing reference" }, { status: 400 });
    }

    const order = await getOrderByNumber(reference);
    if (!order) {
      console.warn(`Webhook received for non-existent order: ${reference}`);
      return NextResponse.json({ error: "Order not found" }, { status: 404 });
    }

    if (status === "success" || status === "paid") {
      await updateOrderPayment(reference, "paid", trxId, "confirmed");
      console.log(`✓ Order ${reference} verified and marked as PAID via webhook. TrxID: ${trxId}`);

      // Forward to Discord webhook notification if configured
      if (process.env.DISCORD_WEBHOOK_URL) {
        try {
          const { sendOrderDiscordNotification } = await import("@/lib/discord");
          const updatedOrder = await getOrderByNumber(reference);
          if (updatedOrder) {
            await sendOrderDiscordNotification(updatedOrder);
          }
        } catch (discordErr) {
          console.error("Discord notification failed in webhook:", discordErr);
        }
      }
    } else {
      await updateOrderPayment(reference, "failed", trxId);
      console.log(`Order ${reference} marked as FAILED via webhook.`);
    }

    return NextResponse.json({ ok: true, received: true });
  } catch (err: any) {
    console.error("Webhook processing error:", err);
    return NextResponse.json({ error: err.message || "Webhook processing failed" }, { status: 500 });
  }
}

import crypto from "crypto";

const RETURN_SECRET = "REDACTED";
const WEBHOOK_SECRET = "REDACTED";

process.env.LORA_RETURN_HMAC_TOKEN = REDACTED;
process.env.LORA_WEBHOOK_HMAC_TOKEN = REDACTED;

import { verifyReturnSignature, verifyWebhookSignature } from "../lib/lorahost.ts";

console.log("=== Running LoraHost Cryptographic Signature Verification ===");

// 1. Test Return URL Signature
const sampleParams = {
  amount: "520",
  reference: "BNP-20261101-9999",
  session_id: "sess_test_123",
  status: "success",
  trx_id: "TRX_987654321",
};

// Compute expected canonical HMAC
const canonical = Object.keys(sampleParams)
  .sort()
  .map((k) => `${k}=${encodeURIComponent(sampleParams[k])}`)
  .join("&");

const validReturnSig = crypto.createHmac("sha256", RETURN_SECRET).update(canonical).digest("hex");

// Test valid return
const returnOk = verifyReturnSignature({ ...sampleParams, sig: validReturnSig });
if (returnOk) {
  console.log("✓ Return URL valid signature verified correctly.");
} else {
  console.error("✗ Return URL valid signature failed verification.");
  process.exit(1);
}

// Test tampered return
const returnTampered = verifyReturnSignature({ ...sampleParams, amount: "100", sig: validReturnSig });
if (!returnTampered) {
  console.log("✓ Tampered return URL parameters rejected correctly.");
} else {
  console.error("✗ Tampered return URL parameters were wrongly accepted.");
  process.exit(1);
}

// 2. Test Webhook Signature
const rawWebhookBody = JSON.stringify({
  reference: "BNP-20261101-9999",
  status: "success",
  trx_id: "TRX_987654321",
  amount: 520,
  session_id: "sess_test_123",
});

const validWebhookSig = crypto.createHmac("sha256", WEBHOOK_SECRET).update(rawWebhookBody).digest("hex");

const webhookOk = verifyWebhookSignature(rawWebhookBody, validWebhookSig);
if (webhookOk) {
  console.log("✓ Webhook raw body signature verified correctly.");
} else {
  console.error("✗ Webhook raw body signature failed verification.");
  process.exit(1);
}

const webhookTampered = verifyWebhookSignature(rawWebhookBody + " ", validWebhookSig);
if (!webhookTampered) {
  console.log("✓ Tampered webhook payload rejected correctly.");
} else {
  console.error("✗ Tampered webhook payload was wrongly accepted.");
  process.exit(1);
}

console.log("\nAll cryptographic security verifications passed successfully!");

